query Query($where: ProductStrategyProcessBOMWhereInput, $orderBy: [ProductStrategyProcessBOMOrderByInput!], $first: Int, $after: String) {
  productStrategyProcessBOM(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {

        active
        actualUsage
    componentType
    standardPackQuantity
    defaultPackaging
        maximumUsage
        minimumUsage
        order
        productionOffalAllowed
        setupOffalAllowed
        standardUsage
        transferSerial
        useOnWorkOrder
        externalId
        reference
      componentPackagingMaterial {code id name}
       consumptionMode {name id}

      }
    }
  }
}

